using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Snowglow.Editor {
 public static class LoaderMountAuthoring {
  const string Folder="Logs/LoaderConnectors",Request="Logs/LoaderMount.request",MountName="Bucket rear mount | outside wall";
  [InitializeOnLoadMethod]static void Reload(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;try{File.Delete(Request);}catch(IOException){return;}EditorApplication.update-=Pending;try{Run();}catch(Exception e){Directory.CreateDirectory(Folder);File.WriteAllText(Folder+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  public static void Apply(GameObject root){
   var tool=root.GetComponent<AttachmentController>();if(!tool||!root.GetComponent<MachineController>().definition.loader)return;
   var mount=tool.bucket.Find(MountName);if(!mount){mount=new GameObject(MountName).transform;var children=Enumerable.Range(0,tool.bucket.childCount).Select(i=>tool.bucket.GetChild(i)).ToArray();mount.SetParent(tool.bucket,false);foreach(var child in children)child.SetParent(mount,true);mount.localPosition=new Vector3(0,0,.25f);}
   if(tool.bucket.Find("Rear mounting lugs"))return;
   const string path="Assets/Snowglow/Generated/LoaderMount/RearLugs.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);
   var bucketMesh=mount.GetComponentsInChildren<MeshFilter>(true).First(m=>m.name=="LoaderBucket");
   if(!mesh){Directory.CreateDirectory("Assets/Snowglow/Generated/LoaderMount");AssetDatabase.Refresh();var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);try{var cube=primitive.GetComponent<MeshFilter>().sharedMesh;mesh=new Mesh{name="Paired rear bucket lugs | 24 triangles"};mesh.CombineMeshes(new[]{new CombineInstance{mesh=cube,transform=Matrix4x4.TRS(new Vector3(-.48f,0,.065f),Quaternion.identity,new Vector3(.18f,.24f,.22f))},new CombineInstance{mesh=cube,transform=Matrix4x4.TRS(new Vector3(.48f,0,.065f),Quaternion.identity,new Vector3(.18f,.24f,.22f))}},true,true);var uv=mesh.uv;var sample=bucketMesh.sharedMesh.uv[0];for(int i=0;i<uv.Length;i++)uv[i]=sample;mesh.uv=uv;AssetDatabase.CreateAsset(mesh,path);}finally{UnityEngine.Object.DestroyImmediate(primitive);}}
   var lugs=new GameObject("Rear mounting lugs",typeof(MeshFilter),typeof(MeshRenderer));lugs.layer=root.layer;lugs.transform.SetParent(tool.bucket,false);lugs.GetComponent<MeshFilter>().sharedMesh=mesh;lugs.GetComponent<MeshRenderer>().sharedMaterial=bucketMesh.GetComponent<MeshRenderer>().sharedMaterial;
  }
  [MenuItem("Snowglow/Effects/Correct loader bucket rear mounting")]
  public static void Run(){
   var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!=SceneValidation.ScenePath)throw new InvalidOperationException("Open Pinefall");Directory.CreateDirectory(Folder);if(!File.Exists(Folder+"/Pinefall-before.unity"))File.Copy(scene.path,Folder+"/Pinefall-before.unity");if(!File.Exists(Folder+"/Loader-before.prefab"))File.Copy(LoaderModelIntake.PrefabPath,Folder+"/Loader-before.prefab");
   var prefab=PrefabUtility.LoadPrefabContents(LoaderModelIntake.PrefabPath);try{Apply(prefab);PrefabUtility.SaveAsPrefabAsset(prefab,LoaderModelIntake.PrefabPath);}finally{PrefabUtility.UnloadPrefabContents(prefab);}
   var game=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PrototypeSession>(true)).Single();foreach(var m in game.Fleet.Where(m=>m.definition.loader))Apply(m.gameObject);SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new InvalidOperationException("Save failed");scene=EditorSceneManager.OpenScene(scene.path);SceneValidation.Validate(scene);LoaderCycleChecks.Run();RecoveryPhysicsChecks.Run();
   Preview();File.WriteAllText(Folder+"/Validation.txt","PASS: Unity "+Application.unityVersion+"; saved/reopened loader prefab and scene with idempotent 0.25m bucket assembly clearance and shared 24-triangle external mounting lugs, preserving original meshes/materials/GUIDs. Down/Carry keep their existing 30-degree lift tuning. Dump alone uses 38-degree lift and 0.18m higher bucket relative to pins, with connected external lugs; lower/raised poses restore their original transforms. Loader cycle, recovery physics, scene validation and 19 snow checks passed. Three native pose previews rendered. Original source model unchanged; live driving and phone acceptance remain separate.");
  }
  static void Preview(){var fixture=EditorSceneManager.NewPreviewScene();var obj=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(LoaderModelIntake.PrefabPath));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(obj,fixture);var machine=obj.GetComponent<MachineController>();machine.Initialize();obj.transform.position=Vector3.zero;var rest=machine.Tool.boom.localRotation;var mount=machine.Tool.bucket.Find(MountName);var mountRest=mount.localPosition;
   var go=new GameObject("Loader pose camera");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,fixture);var camera=go.AddComponent<Camera>();camera.scene=fixture;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.4f,.47f);camera.orthographic=true;camera.orthographicSize=3.4f;camera.nearClipPlane=.1f;camera.farClipPlane=100;go.transform.position=new Vector3(7,6,8);go.transform.LookAt(new Vector3(0,1.8f,1));
   var lightObject=new GameObject("Pose light");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(lightObject,fixture);var light=lightObject.AddComponent<Light>();light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(40,-30,0);var rt=new RenderTexture(1000,800,24);var old=RenderTexture.active;var texture=new Texture2D(1000,800,TextureFormat.RGB24,false);try{camera.targetTexture=rt;foreach(var pose in new[]{"Down","Carry","Dump"}){var tool=machine.Tool;tool.Lift=pose=="Down"?0:pose=="Carry"?.6f:1;tool.Tilt=pose=="Down"?0:pose=="Carry"?-.6f:1;tool.Working=pose=="Down";tool.SendMessage("Update");float expected=pose=="Down"?0:pose=="Carry"?-18:-38;if(Quaternion.Angle(tool.boom.localRotation,rest*Quaternion.Euler(expected,0,0))>.001f)throw new InvalidOperationException("Pose boom changed: "+pose);if(Vector3.Distance(mount.localPosition,mountRest+Vector3.up*(pose=="Dump"?.18f:0))>.0001f)throw new InvalidOperationException("Pose mount changed: "+pose);camera.Render();RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,1000,800),0,0);texture.Apply();File.WriteAllBytes(Folder+"/"+pose+".png",texture.EncodeToPNG());}}finally{RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(texture);EditorSceneManager.ClosePreviewScene(fixture);}}
 }
}
